import React, { useState } from 'react';

const PenetrationTestingMindset = () => {
  const [phases, setPhases] = useState([
    'Reconnaissance',
    'Scanning',
    'Gaining Access',
    'Maintaining Access',
    'Covering Tracks'
  ]);

  const [currentPhaseIndex, setCurrentPhaseIndex] = useState(0);

  const handleNextPhase = () => {
    setCurrentPhaseIndex(prev => prev < phases.length - 1 ? prev + 1 : prev);
  };

  const handlePrevPhase = () => {
    setCurrentPhaseIndex(prev => prev > 0 ? prev - 1 : prev);
  };

  return (
    <div>
      <h1>Penetration Testing Mindset</h1>
      <div>
        <h2>Current Phase: {phases[currentPhaseIndex]}</h2>
        <p>Phase {currentPhaseIndex + 1} of {phases.length}</p>
      </div>
      <div>
        <button onClick={handlePrevPhase}>Previous Phase</button>
        <button onClick={handleNextPhase}>Next Phase</button>
      </div>
      {/* Add key mindset principles section here */}
    </div>
  );
};
